try:
    import datetime
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict) and isinstance(d.get('products'), list):
            hol = ['2026-10-16', '2026-12-25', '2026-12-26', '2027-01-01']
            try:
                today = datetime.date.fromisoformat(str(vars.get('now'))[:10])
            except Exception:
                today = datetime.date(2026, 10, 14)
            bds = []
            x = today
            while len(bds) < 3:
                x = x + datetime.timedelta(days=1)
                if x.weekday() < 5 and x.isoformat() not in hol:
                    bds.append(x.isoformat())
            for p in d['products']:
                if not isinstance(p, dict):
                    continue
                if p.get('type') == 'car_loan':
                    p['handling'] = 'No promise, no floor, no note. Transfer to queue restructuring.'
                    continue
                c = int(round(float(p.get('past_due') or 0) * 100))
                r = 40 if p.get('type') == 'credit_card' else 25
                p['floor'] = ((c * r + 50) // 100) / 100.0
                early = int(p.get('days_late') or 0) <= 10
                p['band'] = 'early' if early else 'late'
                p['deadline'] = bds[2] if early else bds[1]
                p['attempts'] = 1 if early else 2
            d['today'] = today.isoformat()
            d['business_days_after_today'] = bds
            d['what_to_do_next'] = 'State every late product in this order, then ask once whether the customer can pay the full past due of every product that is not a car loan today.'
except Exception:
    pass

